MERGE [sales].[CustomerPaymentTerms] t USING(VALUES('IMMEDIATE','Immediate',0,1),('NET15','Net 15 Days',15,0),('NET30','Net 30 Days',30,0),('NET45','Net 45 Days',45,0),('NET60','Net 60 Days',60,0))s([Code],[Name],[Days],[Default]) ON t.[PaymentTermCode]=s.[Code] WHEN MATCHED THEN UPDATE SET [PaymentTermName]=s.[Name],[DueDays]=s.[Days],[IsDefault]=s.[Default],[IsActive]=1 WHEN NOT MATCHED THEN INSERT([PaymentTermCode],[PaymentTermName],[DueDays],[IsDefault],[IsActive],[CreatedBy])VALUES(s.[Code],s.[Name],s.[Days],s.[Default],1,'database-seed');
